import { test, expect } from '@playwright/test';

test.describe('Notification Auto-Dismiss', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://your-application-url.com');
  });

  test('should display notification', async ({ page }) => {
    await page.click(getByRole('button', { name: /show notification/i }));
    const notification = await page.getByRole('alert');
    await expect(notification).toBeVisible();
  });

  test('should auto-dismiss notification after 5 seconds', async ({ page }) => {
    await page.click(getByRole('button', { name: /show notification/i }));
    const notification = await page.getByRole('alert');
    await expect(notification).toBeVisible();
    await page.waitForTimeout(5000);
    await expect(notification).not.toBeVisible();
  });
});
